// Step 3: Fetch Mandi Data (GitHub mandi-data repository / Agmarknet Daily Feed)
// Simulating clean GitHub / Agmarknet CSV fetch
const rawCsv = `date,state,district,market,commodity,variety,grade,min_price,max_price,modal_price
2026-09-28,Tamil Nadu,Trichy,Trichy,Tomato,Local,Grade A,2400,3200,2800
2026-09-28,Tamil Nadu,Chennai,Koyambedu,Tomato,Local,Grade A,3000,4000,3500
2026-09-28,Tamil Nadu,Coimbatore,Coimbatore,Tomato,Hybrid,Grade A,2800,3600,3200
2026-09-28,Tamil Nadu,Madurai,Madurai,Tomato,Local,Grade A,2200,3100,2700
2026-09-28,Tamil Nadu,Trichy,Trichy,Coconut,Pollachi Regular,Grade A,2400,3100,2800
2026-09-28,Tamil Nadu,Chennai,Koyambedu,Coconut,Pollachi Regular,Grade A,3000,3800,3400
2026-09-28,Tamil Nadu,Trichy,Trichy,Banana,Poovan,Grade A,2000,2700,2400
2026-09-28,Tamil Nadu,Chennai,Koyambedu,Banana,Poovan,Grade A,2600,3400,3000
2026-09-28,Tamil Nadu,Trichy,Trichy,Onion,Small Red Bellary,Export Grade,4600,5600,5200
2026-09-28,Tamil Nadu,Chennai,Koyambedu,Onion,Small Red Bellary,Export Grade,5800,6900,6400`;

const farmer = $input.first().json;
return [{ json: { rawCsv, farmer } }];

// Step 4: Parse CSV lines & Filter State (Tamil Nadu)
const item = $input.first().json;
const lines = item.rawCsv.trim().split('\n');
const headers = lines[0].split(',');

const parsed = [];
for (let i = 1; i < lines.length; i++) {
  const row = lines[i].split(',');
  const obj = {};
  headers.forEach((h, idx) => {
    const val = row[idx];
    obj[h.trim()] = isNaN(val) ? val.trim() : Number(val);
  });
  if (obj.state === 'Tamil Nadu') {
    parsed.push(obj);
  }
}

return [{ json: { records: parsed, farmer: item.farmer } }];

// Step 5: Filter Commodity & Normalize Prices (1 Quintal = 100 KG)
const item = $input.first().json;
const cropQuery = item.farmer.crop.toLowerCase().trim();

let filtered = item.records.filter(r => {
  const c = r.commodity.toLowerCase();
  return c === cropQuery || c.includes(cropQuery) || cropQuery.includes(c);
});

if (filtered.length === 0) {
  filtered = item.records.slice(0, 4);
}

const normalized = filtered.map(r => ({
  market: r.market,
  district: r.district,
  commodity: r.commodity,
  modalPriceQuintal: r.modal_price,
  modalPricePerKg: r.modal_price / 100,
  minPricePerKg: r.min_price / 100,
  maxPricePerKg: r.max_price / 100
}));

return [{ json: { mandis: normalized, farmer: item.farmer } }];

// Step 6: Market Analysis (Price Spread & Demand Scoring)
const item = $input.first().json;
const mandis = item.mandis;

const scored = mandis.map(m => {
  let demand = 'Medium';
  if (m.district === 'Chennai') demand = 'High';
  else if (m.district === 'Coimbatore') demand = 'High';
  else if (m.district === 'Madurai') demand = 'Low';

  return {
    ...m,
    demand,
    spread: m.maxPricePerKg - m.minPricePerKg
  };
});

return [{ json: { scoredMandis: scored, farmer: item.farmer } }];

// Step 7: Market Opportunity Comparison
const item = $input.first().json;
const mandis = item.scoredMandis;
const farmer = item.farmer;

const chennai = mandis.find(m => m.district === 'Chennai') || { modalPricePerKg: 35, modalPriceQuintal: 3500 };
const trichy = mandis.find(m => m.district === 'Trichy') || { modalPricePerKg: 28, modalPriceQuintal: 2800 };
const coimbatore = mandis.find(m => m.district === 'Coimbatore') || { modalPricePerKg: 32, modalPriceQuintal: 3200 };
const madurai = mandis.find(m => m.district === 'Madurai') || { modalPricePerKg: 27, modalPriceQuintal: 2700 };

const comparison = [
  { market: 'Trichy', shortName: 'TRICHY', pricePerKg: trichy.modalPricePerKg, note: 'Local Base', isLocal: true },
  { market: 'Chennai', shortName: 'CHENNAI', pricePerKg: chennai.modalPricePerKg, note: 'Best Market (+₹' + (chennai.modalPricePerKg - farmer.expectedPrice) + '/kg)', isLocal: false },
  { market: 'Coimbatore', shortName: 'COIMBATORE', pricePerKg: coimbatore.modalPricePerKg, note: '+₹4/kg', isLocal: false },
  { market: 'Madurai', shortName: 'MADURAI', pricePerKg: madurai.modalPricePerKg, note: '-₹1/kg', isLocal: false }
];

return [{ json: { comparison, bestMarket: chennai, localMarket: trichy, farmer } }];

// Step 8: Buyer Matching (AgriLink Verified B2B Wholesale Network)
const item = $input.first().json;

const buyer = {
  id: 'buyer-koyambedu',
  name: 'Koyambedu Wholesale Mart',
  location: 'Chennai',
  requiredQuantityKg: item.farmer.quantityKg,
  targetPrice: item.bestMarket.modalPricePerKg,
  paymentTerms: 'WhatsApp-coordinated escrow on dispatch',
  badge: 'B2B Wholesale Buyer',
  verified: true,
  isBestMatch: true
};

return [{ json: { ...item, buyer } }];

// Step 9: Transport Estimation (Corridor Distance & Freight Cost)
const item = $input.first().json;

const transport = {
  partner: 'Tamil Nadu Agro Logistics',
  vehicle: 'Eicher Pro 2049 (14 FT)',
  capacityKg: 3000,
  estimatedCost: 3600,
  estimatedRatePerKg: 1.8,
  distanceKm: 330,
  corridor: 'NH38 / NH45 Direct Highway',
  transitHours: '~6 Hours'
};

return [{ json: { ...item, transport } }];

// Step 10: Opportunity Score & Net Advantage Calculation
const item = $input.first().json;
const farmerExp = item.farmer.expectedPrice;
const marketPrice = item.bestMarket.modalPricePerKg;
const transportCostPerKg = 2.0; // conservative ₹2/kg freight allocation

const grossDifference = marketPrice - farmerExp; // e.g. 35 - 28 = ₹7/kg
const netAdvantagePerKg = Math.max(0, grossDifference - transportCostPerKg); // 7 - 2 = ₹5/kg
const totalOpportunity = Math.round(netAdvantagePerKg * item.farmer.quantityKg); // 5 * 2000 = ₹10,000

const opportunityScore = {
  marketPricePerKg: marketPrice,
  farmerExpectedPrice: farmerExp,
  grossDiffPerKg: grossDifference,
  estimatedTransportPerKg: transportCostPerKg,
  netAdvantagePerKg: netAdvantagePerKg,
  totalOpportunityAmount: totalOpportunity
};

return [{ json: { ...item, opportunityScore } }];

// Step 11: AI Explanation ('Why This Market')
const item = $input.first().json;
const opp = item.opportunityScore;

const aiInsight = {
  recommendation: 'CHENNAI HAS THE BEST ESTIMATED OPPORTUNITY',
  summary: 'Chennai shows a higher observed mandi price (+₹' + opp.grossDiffPerKg + '/kg over expected) with high institutional buyer demand, offsetting the ~₹2/kg NH45 transport cost and unlocking +₹' + opp.totalOpportunityAmount.toLocaleString() + ' net opportunity.',
  whyReasons: [
    'Higher indicative wholesale APMC price (+₹' + opp.grossDiffPerKg + '/kg gross)',
    'High B2B institutional demand (Koyambedu Wholesale Mart)',
    'Quantity match: ' + item.farmer.quantityKg.toLocaleString() + ' KG lot size',
    'Direct NH45 corridor (~330 KM with direct freight availability)',
    'Estimated transport accounted for (~₹' + opp.estimatedTransportPerKg + '/kg deduction)'
  ],
  disclaimer: 'AI estimate — not a guaranteed selling price.'
};

return [{ json: { ...item, aiInsight } }];

// Step 12: Generate AI Promotion (Bilingual Content)
const item = $input.first().json;
const crop = item.farmer.crop;
const qty = item.farmer.quantityKg.toLocaleString();
const loc = item.farmer.location;
const price = item.bestMarket.modalPricePerKg;

const promotion = {
  caption: '🍅 Fresh ' + item.farmer.quality + ' ' + crop + '\n📦 Quantity: ' + qty + ' KG\n📍 Farm Origin: ' + loc + ', Tamil Nadu\n💰 Indicative Market Rate: ₹' + price + ' / KG\n🤝 Available for verified B2B purchase via AgriLink AI.',
  captionTa: '🍅 புதிய ' + crop + ' (' + qty + ' கிலோ)\n📍 பண்ணை: ' + loc + ', தமிழ்நாடு\n💰 உத்தேச சந்தை விலை: ₹' + price + ' / கிலோ\n🤝 AgriLink AI தளம் மூலம் நேரடி B2B கொள்முதல்.',
  channels: ['WhatsApp Wholesale Broadcast', 'AgriLink Buyer Portal', 'Koyambedu Terminal Feed']
};

return [{ json: { ...item, promotion } }];

// Step 13: Order & WhatsApp Payment Coordination
const item = $input.first().json;

const order = {
  orderId: 'AGRI-2026-8842',
  status: 'Ready for Dispatch',
  totalValue: item.bestMarket.modalPricePerKg * item.farmer.quantityKg,
  buyerName: item.buyer.name,
  whatsappPaymentCoordinated: true
};

return [{ json: { ...item, order } }];

// Step 14: Logistics Route & Telemetry
const item = $input.first().json;

const logistics = {
  route: item.farmer.location + ' Farm Gate ➔ Chennai Koyambedu',
  corridorKm: 330,
  speedKmH: 52,
  currentCheckpoint: 'Villupuram (NH45)',
  status: 'Tracking Active',
  etaHours: 6
};

return [{ json: { ...item, logistics } }];
